const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const h = escapeHTML;
const statusNames = {available:'Доступен',issued:'Выдан',accepted:'Принят исполнителем',queued:'В очереди',rejected:'Отказ исполнителя',planned:'В графике',inProgress:'В работе',paused:'Пауза',aiPending:'Проверяет ИИ',submitted:'На проверке',revision:'Доработка',approved:'Принят мастером',cancelled:'Отменён',superseded:'Предыдущая версия'};
